firebase.initializeApp({"apiKey":"AIzaSyBqdYjDoxDLVccK3g7Fu1g5a3Is6jWNcRQ","authDomain":"vocation-sl-8c645.firebaseapp.com","projectId":"vocation-sl-8c645","storageBucket":"vocation-sl-8c645.firebasestorage.app","messagingSenderId":"598626797751","appId":"1:598626797751:web:1316cea75731fea3e7a532"});

// Alerts sent with a "notification" part are shown by Firebase automatically;
// tapping one opens the link set by the server (the Alerts screen).
const messaging = firebase.messaging();

// Fallback: if a tapped alert has no link, open or focus the Alerts screen.
self.addEventListener('notificationclick', (event) => {
  const route = (event.notification.data && event.notification.data.route) || '/alerts';
  const url = new URL('/#' + route, self.location.origin).href;
  event.notification.close();
  event.waitUntil((async () => {
    const tabs = await clients.matchAll({ type: 'window', includeUncontrolled: true });
    for (const tab of tabs) {
      if (tab.url.startsWith(self.location.origin)) {
        await tab.focus();
        return tab.navigate(url);
      }
    }
    return clients.openWindow(url);
  })());
});